package com.german_software_engineers.trainerappmodel.Model;

import com.german_software_engineers.trainerappmodel.Enumerations.TrainingsTypes;
import com.german_software_engineers.trainerappmodel.Legacy.Schedule;

import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import java.io.File;
import java.io.FileWriter;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

public class XMLParserTest {
    @Rule
    public TemporaryFolder temporaryFolder = new TemporaryFolder();

    @Test
    public void writeAndParseFilePreservesTrainingsType() throws Exception {
        Model sourceModel = new Model();
        Schedule sourceSchedule = new Schedule("Leg day");
        sourceSchedule.setTrainingsType(TrainingsTypes.maximum_strength);
        sourceSchedule.setRepetitions(5);
        sourceSchedule.setPauseTime(90);
        sourceSchedule.setSets(3);
        sourceSchedule.setSpeed(2);
        sourceModel.addSchedule(sourceSchedule);

        File file = temporaryFolder.newFile("schedule.xml");
        XMLParser writer = new XMLParser(sourceModel);
        writer.setCurrentApplicationVersion("test");
        assertTrue(writer.writeFile(file));

        Model parsedModel = new Model();
        assertTrue(new XMLParser(parsedModel).parseFile(file));
        assertEquals(TrainingsTypes.maximum_strength,
                parsedModel.getSchedule("Leg day").getTrainingsType());
    }

    @Test
    public void parseLegacyFileUsesDefaultTrainingsType() throws Exception {
        File file = temporaryFolder.newFile("legacy-schedule.xml");
        FileWriter writer = new FileWriter(file);
        writer.write("<trainingsschedule appversion=\"legacy\">"
                + "<schedule name=\"Legacy\" repetitions=\"10\" pause=\"60\" sets=\"3\" speed=\"2\"/>"
                + "</trainingsschedule>");
        writer.close();

        Model parsedModel = new Model();
        assertTrue(new XMLParser(parsedModel).parseFile(file));
        assertEquals(TrainingsTypes.strength_endurance,
                parsedModel.getSchedule("Legacy").getTrainingsType());
    }
}

